   296  /**
   297   * xmlFuzzEntityLoader:
   298   *
   299   * The entity loader for fuzz data.
   300   */
   301  xmlParserInputPtr
   302  xmlFuzzEntityLoader(const char *URL, const char *ID ATTRIBUTE_UNUSED,
   303                      xmlParserCtxtPtr ctxt) {
   304      xmlParserInputPtr input;
   305      xmlFuzzEntityInfo *entity;
   306
   307      if (URL == NULL)
   308          return(NULL);
   309      entity = xmlHashLookup(fuzzData.entities, (xmlChar *) URL);
   310      if (entity == NULL)
   311          return(NULL);
   312
   313      input = xmlNewInputStream(ctxt);
   314      input->filename = NULL;
   315      input->buf = xmlParserInputBufferCreateMem(entity->data, entity->size,
   316                                                 XML_CHAR_ENCODING_NONE);
   317      input->base = input->cur = xmlBufContent(input->buf->buffer);
   318      input->end = input->base + entity->size;
   319
   320      return input;
   321  }
