   323  /**
   324   * xmlFuzzExtractStrings:
   325   *
   326   * Extract C strings from input data. Use exact-size allocations to detect
   327   * potential memory errors.
   328   */
   329  size_t
   330  xmlFuzzExtractStrings(const char *data, size_t size, char **strings,
   331                        size_t numStrings) {
   332      const char *start = data;
   333      const char *end = data + size;
   334      size_t i = 0, ret;
   335
   336      while (i < numStrings) {
   337          size_t strSize = end - start;
   338          const char *zero = memchr(start, 0, strSize);
   339
   340          if (zero != NULL)
   341              strSize = zero - start;
   342
   343          strings[i] = xmlMalloc(strSize + 1);
   344          memcpy(strings[i], start, strSize);
   345          strings[i][strSize] = '\0';
   346
   347          i++;
   348          if (zero != NULL)
   349              start = zero + 1;
   350          else
   351              break;
   352      }
   353
   354      ret = i;
   355
   356      while (i < numStrings) {
   357          strings[i] = NULL;
   358          i++;
   359      }
   360
   361      return(ret);
   362  }
